syntax:
namespace {  // Anonymous namespace declaration
    // Declarations here (e.g., int i;) have internal linkage
    // The compiler generates a unique name for this namespace,
    // e.g., equivalent to 'namespace __unique_compiler_id { ... }'
}

code_example:
#include <iostream>
namespace A {
    namespace {
        int i;  // Variable with internal linkage, unique to this translation unit
        int j;  // Another variable with internal linkage
    }
    void g() { i++; }  // Function accessing the anonymous namespace's i
}
using namespace A;  // Brings A into scope, but anonymous namespace remains internal
